+function truncateString(str, maxLength, suffix = '...[TRUNCATED]') {
+  if (str.length <= maxLength) return str;
+  const graphemeRegex = /(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|.)\p{M}*/gu;
+  let truncatedStr = '';
+  let match;
+  while ((match = graphemeRegex.exec(str)) !== null) {
+    const segment = match[0];
+    if (truncatedStr.length + segment.length > maxLength) break;
+    truncatedStr += segment;
+    if (truncatedStr.length >= maxLength) break;
+  }
+  if (truncatedStr.length > 0) {
+    const lastCode = truncatedStr.charCodeAt(truncatedStr.length - 1);
+    if (lastCode >= 0xd800 && lastCode <= 0xdbff) truncatedStr = truncatedStr.slice(0, -1);
+  }
+  return truncatedStr + suffix;
+}
+const DEFAULT = 8192;
+function truncateForTelemetry(value, maxLength = DEFAULT) {
+  if (value === undefined) return undefined;
+  const t = typeof value;
+  if (t === 'number' || t === 'boolean') return value;
+  if (t === 'function' || t === 'symbol') return undefined;
+  let str = t === 'string' ? value : JSON.stringify(value);
+  if (str.length <= maxLength) return str;
+  return truncateString(str, maxLength, `...[TRUNCATED: original length ${str.length}]`);
+}
+console.log('short str:', JSON.stringify(truncateForTelemetry('hello')));
+console.log('num:', truncateForTelemetry(42));
+console.log('bool:', truncateForTelemetry(true));
+console.log('undef:', truncateForTelemetry(undefined));
+console.log('func:', truncateForTelemetry(() => {}));
+console.log('symbol:', truncateForTelemetry(Symbol('x')));
+console.log('obj:', truncateForTelemetry({ a: 1, b: 'x' }));
+console.log('long ascii (max5):', JSON.stringify(truncateForTelemetry('abcdefghij', 5)));
+console.log('emoji not split (max3):', JSON.stringify(truncateForTelemetry('ab😀cd', 3)));
+console.log('emoji boundary (max4):', JSON.stringify(truncateForTelemetry('ab😀cd', 4)));
+console.log('combining (max3):', JSON.stringify(truncateForTelemetry('éllo', 3)));
+console.log('obj truncated (max5):', JSON.stringify(truncateForTelemetry({ key: 'a very long value here' }, 5)));
